import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CmvPqeTF.js";const g=JSON.parse('{"title":"vShell 设计语言（Islands 岛式）","description":"","frontmatter":{},"headers":[],"relativePath":"ui/vshell-design-language.md","filePath":"ui/vshell-design-language.md","lastUpdated":1791540103000}'),c={name:"ui/vshell-design-language.md"};function r(l,t,n,s,i,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="vshell-设计语言-islands-岛式" tabindex="-1">vShell 设计语言（Islands 岛式） <a class="header-anchor" href="#vshell-设计语言-islands-岛式" aria-label="Permalink to &quot;vShell 设计语言（Islands 岛式）&quot;">​</a></h1><blockquote><p><strong>定位</strong>：本文档是 vShell 自有设计语言的<strong>落地规范</strong>——以 IntelliJ IDEA 设计语言（见仓库内 <code>idea-ui-design-language.md</code>，下称「IDEA 参考」）为源头、 GMark 岛式实现（见仓库内 <code>gmark-design-language.md</code>，下称「GMark 参考」） 为岛式落地参照，针对 SSH 客户端形态定制。数值与规则以本文档为准。 <strong>基线</strong>：artifacts 分支界面重写（2026-10），vShell 1.x。 <strong>维护</strong>：改 token / 组件规格 / 交互规则时同步更新本文档对应条目， 先改这里再改代码。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-设计原则">设计原则</a></li><li><a href="#2-主题与-token">主题与 Token</a></li><li><a href="#3-布局系统islands-岛式">布局系统（Islands 岛式）</a></li><li><a href="#4-组件规范">组件规范</a></li><li><a href="#5-终端区中心岛">终端区（中心岛）</a></li><li><a href="#6-sftp底部工具窗">SFTP（底部工具窗）</a></li><li><a href="#7-服务器监控底部工具窗">服务器监控（底部工具窗）</a></li><li><a href="#8-连接树左工具窗">连接树（左工具窗）</a></li><li><a href="#9-设置">设置</a></li><li><a href="#10-交互模型">交互模型</a></li><li><a href="#11-状态设计">状态设计</a></li><li><a href="#12-与-idea--gmark-参考的差异决策记录">与 IDEA / GMark 参考的差异决策记录</a></li><li><a href="#13-代码索引">代码索引</a></li></ol><hr><h2 id="_1-设计原则" tabindex="-1">1. 设计原则 <a class="header-anchor" href="#_1-设计原则" aria-label="Permalink to &quot;1. 设计原则&quot;">​</a></h2><p><strong>继承（IDEA 参考 §1 精选八条）</strong></p><ol><li>工具优先，内容至上——铬框低调，焦点留给终端会话与文件操作。</li><li>一切皆 Token——颜色/度量出自单一事实源，组件零裸值。</li><li>灰阶为主体，单一品牌蓝为强调——彩色只用于选中/焦点/链接/语义/ 连接状态/图表。</li><li>分层背景表达层级，不靠阴影（阴影仅浮动层：弹窗/通知）。</li><li>1px 边框 + 低透明度叠加做交互反馈。</li><li>状态集完整：default / hover / pressed / selected / focused / disabled。</li><li>键盘优先——快捷键完备，鼠标是补充。</li><li>明暗同构——token 镜像命名，切主题零结构变化。</li></ol><p><strong>vShell 特有四条</strong></p><ol start="9"><li><strong>岛式布局</strong>——窗口是画布，所有面板是浮其上的圆角岛（Islands 模型， 同 GMark）。</li><li><strong>会话为中心</strong>——终端会话是一等公民：标签即会话、保活切换不丢缓冲、 状态点常显。</li><li><strong>连接状态可视化</strong>——连接的 connecting / online / offline / error 四态有专属色 token，在连接树、标签、状态栏三处同色出现。</li><li><strong>Naive UI 为基座</strong>——表单/弹窗/下拉等交互控件用 Naive UI 经 token 桥接驱动；仅壳层（条/工具窗/标签行/状态栏）自绘 V* 组件。不做全自绘。</li></ol><hr><h2 id="_2-主题与-token" tabindex="-1">2. 主题与 Token <a class="header-anchor" href="#_2-主题与-token" aria-label="Permalink to &quot;2. 主题与 Token&quot;">​</a></h2><h3 id="_2-1-三层同源架构" tabindex="-1">2.1 三层同源架构 <a class="header-anchor" href="#_2-1-三层同源架构" aria-label="Permalink to &quot;2.1 三层同源架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frontend/src/styles/global.css        ← 唯一事实源（亮暗成对镜像命名）</span></span>
<span class="line"><span>   ├─ uno.config.ts theme 引用 var(--*)</span></span>
<span class="line"><span>   └─ App.vue 运行时 getComputedStyle 现读真实值 → NConfigProvider themeOverrides</span></span></code></pre></div><ul><li><strong>Naive 联动纪律（GMark R1 教训）</strong>：Naive 内部 JS 解析颜色，<code>var()</code> 字符串会静默失效。themeOverrides 必须运行时现读 <code>getComputedStyle</code> 的真实值注入，且 computed 显式依赖 <code>settings.themeMode</code>（否则主题切换 后不重读）。</li><li><strong>规则</strong>：组件零裸色值、零裸字号；圆角只用 {4,8,12,20}；间距只用 {2,4,6,8,12,16,20,24}；动效 ≤300ms；ECharts / xterm / Monaco 等 canvas 渲染器不能消费 <code>var()</code> 字符串，须经 <code>cssVar()</code> 解析真实值。</li></ul><h3 id="_2-2-islands-背景层级" tabindex="-1">2.2 Islands 背景层级 <a class="header-anchor" href="#_2-2-islands-背景层级" aria-label="Permalink to &quot;2.2 Islands 背景层级&quot;">​</a></h3><p><strong>层次只存在于「岛 vs 画布」之间——所有岛同层同色。</strong></p><table tabindex="0"><thead><tr><th>层</th><th>亮</th><th>暗</th><th>用途</th></tr></thead><tbody><tr><td>画布 canvas</td><td><code>#E9EAEE</code></td><td><code>#2B2D30</code></td><td>窗口底、岛间留白（接缝）</td></tr><tr><td>铬条 chrome</td><td><code>#E9EAEE</code></td><td><code>#2B2D30</code></td><td>工具栏、左条、状态栏——**与画布同色</td></tr><tr><td>（<code>--bg-chrome</code> = canvas，融画布）<strong>，三者与画布构成</strong>一体外框**，</td><td></td><td></td><td></td></tr><tr><td>仅内容面板（左/底部工具窗、中心岛）为浮岛（同 GMark 决策）</td><td></td><td></td><td></td></tr><tr><td>岛（内容面板）</td><td><code>#FFFFFF</code></td><td><code>#1E1F22</code></td><td>左工具窗、中心岛、底部工具窗</td></tr><tr><td>嵌入控件</td><td><code>#FFFFFF</code></td><td><code>#2B2D30</code></td><td>输入框、代码片、嵌入面板底</td></tr><tr><td>反转气泡</td><td><code>#27282E</code></td><td><code>#393B40</code></td><td>tooltip / 深色反转层</td></tr></tbody></table><ul><li>终端内容背景跟随<strong>终端配色方案</strong>（不强制岛色）；方案为 <code>default</code> 时 从主题 token 派生（暗 <code>#1E1F22</code> / 亮 <code>#FFFFFF</code>），与岛同层。</li><li>原生窗口底色（<code>main.go</code> BackgroundColour）取暗画布值，避免启动闪白。</li></ul><h3 id="_2-3-色彩-token-总表" tabindex="-1">2.3 色彩 Token 总表 <a class="header-anchor" href="#_2-3-色彩-token-总表" aria-label="Permalink to &quot;2.3 色彩 Token 总表&quot;">​</a></h3><p><strong>强调与交互（IDEA 蓝，产品决策）</strong></p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th><th>说明</th></tr></thead><tbody><tr><td><code>--color-primary</code></td><td><code>#3871E1</code></td><td><code>#3574F0</code></td><td>品牌蓝：主按钮/焦点/条按钮激活</td></tr><tr><td><code>--selection</code></td><td><code>#D0DFFE</code></td><td><code>#2E436E</code></td><td>列表/树选中块</td></tr><tr><td><code>--tab-selected-bg</code></td><td><code>#E3EBFE</code></td><td><code>#2E436E</code></td><td>标签激活填充</td></tr><tr><td><code>--hover</code></td><td><code>#EDF3FF</code></td><td><code>#393B40</code></td><td>可选项悬停</td></tr><tr><td><code>--hover-gray</code></td><td><code>#EBECF0</code></td><td><code>#43454A</code></td><td>行/标签中性悬停</td></tr><tr><td><code>--hover-overlay</code></td><td><code>rgba(0,0,0,.04)</code></td><td><code>rgba(255,255,255,.10)</code></td><td>图标钮悬停叠加</td></tr><tr><td><code>--pressed-overlay</code></td><td><code>rgba(0,0,0,.08)</code></td><td><code>rgba(255,255,255,.15)</code></td><td>按下叠加</td></tr><tr><td><code>--link</code></td><td><code>#315FBD</code></td><td><code>#6B9BFA</code></td><td>链接</td></tr></tbody></table><p><strong>文字</strong></p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th></tr></thead><tbody><tr><td><code>--text-primary</code></td><td><code>#000000</code></td><td><code>#DFE1E5</code></td></tr><tr><td><code>--text-secondary</code></td><td><code>#494B57</code></td><td><code>#B4B8BF</code></td></tr><tr><td><code>--text-muted</code></td><td><code>#6C707E</code></td><td><code>#9DA0A8</code></td></tr><tr><td><code>--text-disabled</code></td><td><code>#A8ADBD</code></td><td><code>#5A5D63</code></td></tr><tr><td><code>--text-inverted</code></td><td><code>#F0F1F2</code></td><td><code>#CED0D6</code></td></tr></tbody></table><p><strong>边框</strong>（暗色决策偏差见 §12-7）</p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th></tr></thead><tbody><tr><td><code>--border-color</code></td><td><code>#DFE1E5</code></td><td><code>#323538</code></td></tr><tr><td><code>--border-strong</code></td><td><code>#C9CCD6</code></td><td><code>#43454A</code></td></tr><tr><td><code>--border-input</code></td><td><code>#C9CCD6</code></td><td><code>#4E5157</code></td></tr></tbody></table><p><strong>语义</strong></p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th></tr></thead><tbody><tr><td><code>--color-success</code></td><td><code>#208A3C</code></td><td><code>#57965C</code></td></tr><tr><td><code>--color-warning</code></td><td><code>#A46704</code></td><td><code>#BA9752</code></td></tr><tr><td><code>--warning-accent</code></td><td><code>#FFAF0F</code></td><td><code>#F2C55C</code></td></tr><tr><td><code>--color-error</code></td><td><code>#DB3B4B</code></td><td><code>#DB5C5C</code></td></tr><tr><td><code>--color-info</code></td><td><code>#3369D6</code></td><td><code>#6B9BFA</code></td></tr></tbody></table><p><strong>连接状态（vShell 特有）</strong>——树节点圆点、终端标签圆点、状态栏共用：</p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th><th>语义</th></tr></thead><tbody><tr><td><code>--status-connecting</code></td><td><code>#C77D0B</code></td><td><code>#F2C55C</code></td><td>连接建立中</td></tr><tr><td><code>--status-online</code></td><td><code>#208A3C</code></td><td><code>#57965C</code></td><td>会话在线</td></tr><tr><td><code>--status-offline</code></td><td><code>#A8ADBD</code></td><td><code>#6F737A</code></td><td>已断开</td></tr><tr><td><code>--status-error</code></td><td><code>#DB3B4B</code></td><td><code>#DB5C5C</code></td><td>连接失败</td></tr></tbody></table><p><strong>监控图表</strong>（ECharts 经 <code>cssVar()</code> 解析）</p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th></tr></thead><tbody><tr><td><code>--chart-cpu</code></td><td><code>#3871E1</code></td><td><code>#6E9FF7</code></td></tr><tr><td><code>--chart-mem</code></td><td><code>#208A3C</code></td><td><code>#5CA56B</code></td></tr><tr><td><code>--chart-disk</code></td><td><code>#8C5CE0</code></td><td><code>#A98BEB</code></td></tr><tr><td><code>--chart-net-rx</code></td><td><code>#0E9CB8</code></td><td><code>#4FC3F7</code></td></tr><tr><td><code>--chart-net-tx</code></td><td><code>#D9632E</code></td><td><code>#FF8A65</code></td></tr><tr><td><code>--stat-bar-track</code></td><td><code>#EBECF0</code></td><td><code>#393B40</code></td></tr></tbody></table><p><strong>传输方向</strong></p><table tabindex="0"><thead><tr><th>Token</th><th>亮</th><th>暗</th></tr></thead><tbody><tr><td><code>--transfer-up</code></td><td><code>#3871E1</code></td><td><code>#3574F0</code></td></tr><tr><td><code>--transfer-down</code></td><td><code>#208A3C</code></td><td><code>#57965C</code></td></tr></tbody></table><p><strong>阴影</strong>（仅浮动层）：<code>--shadow-elevated</code> 亮 <code>0 8px 24px rgba(0,0,0,.16)</code> / 暗 <code>0 8px 24px rgba(0,0,0,.5)</code>。</p><h3 id="_2-4-岛度量-token-主题无关-root-定义" tabindex="-1">2.4 岛度量 Token（主题无关，<code>:root</code> 定义） <a class="header-anchor" href="#_2-4-岛度量-token-主题无关-root-定义" aria-label="Permalink to &quot;2.4 岛度量 Token（主题无关，\`:root\` 定义）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Token</th><th>值</th><th>用途</th></tr></thead><tbody><tr><td><code>--island-arc</code> / <code>-compact</code></td><td><code>12px</code> / <code>12px</code></td><td>岛圆角（工具窗/中心岛，产品</td></tr><tr><td>决策：12px）</td><td></td><td></td></tr><tr><td><code>--island-bw</code> / <code>-compact</code></td><td><code>6px</code> / <code>4px</code></td><td>岛间画布留白</td></tr><tr><td><code>--bar-arc</code></td><td><code>12px</code></td><td>工具栏/左条/状态栏圆角（铬条融画布后视觉不可见）</td></tr><tr><td><code>--traffic-light-w</code></td><td><code>76px</code></td><td>工具栏红绿灯预留</td></tr></tbody></table><h3 id="_2-5-控件度量-沿-idea-参考-§5" tabindex="-1">2.5 控件度量（沿 IDEA 参考 §5） <a class="header-anchor" href="#_2-5-控件度量-沿-idea-参考-§5" aria-label="Permalink to &quot;2.5 控件度量（沿 IDEA 参考 §5）&quot;">​</a></h3><p>控件 28（紧凑 24）· 行 24 · 工具窗头 41 · 左条钮 40×40（图标 20）· 工具栏高 40 · 状态栏 28 · 标签行 40 · 标签药丸 32 · 焦点环 2px accent · 圆角阶梯 4/8/12/20 · 间距阶梯 2/4/6/8/12/16/20/24（<code>--space-1..8</code>）。</p><h3 id="_2-6-双轨主题" tabindex="-1">2.6 双轨主题 <a class="header-anchor" href="#_2-6-双轨主题" aria-label="Permalink to &quot;2.6 双轨主题&quot;">​</a></h3><ul><li><strong>通用主题</strong>（UI 铬框）：亮/暗两套，<code>data-theme</code> 属性驱动 CSS 变量； <code>⌘⇧T</code> / 工具栏按钮 / 设置页切换；localStorage 持久化，默认暗色。</li><li><strong>终端配色方案</strong>：注册表独立（默认/Solarized 暗/亮/Dracula/Monokai/ One Dark）；<code>default</code> 跟随通用主题，其余固定；修改对已开会话实时生效。</li><li>Monaco 主题跟随通用主题（<code>vs</code> / <code>vs-dark</code>，watcher 实时切换）。</li><li>字体：UI 跟随设置（系统栈为默认，可换）；终端等宽字体独立设置； 编辑器用 <code>--font-mono</code> 栈。</li></ul><hr><h2 id="_3-布局系统-islands-岛式" tabindex="-1">3. 布局系统（Islands 岛式） <a class="header-anchor" href="#_3-布局系统-islands-岛式" aria-label="Permalink to &quot;3. 布局系统（Islands 岛式）&quot;">​</a></h2><h3 id="_3-1-骨架" tabindex="-1">3.1 骨架 <a class="header-anchor" href="#_3-1-骨架" aria-label="Permalink to &quot;3.1 骨架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 画布（--bg-canvas）                                        │</span></span>
<span class="line"><span>│ ┌────────────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>│ │ 主工具栏岛（40，bar-arc 12，左 76px 红绿灯留位，拖拽区）│   │</span></span>
<span class="line"><span>│ └────────────────────────────────────────────────────┘   │</span></span>
<span class="line"><span>│ ┌──┐ ┌──────────┐ ┌──────────────────────┐               │</span></span>
<span class="line"><span>│ │左│ │左工具窗岛 │ │ 中心岛                 │               │</span></span>
<span class="line"><span>│ │条│ │(连接/密钥/ │ │ 会话标签 40            │               │</span></span>
<span class="line"><span>│ │通│ │ 配置/转发/ │ │ xterm / Monaco        │               │</span></span>
<span class="line"><span>│ │高│ │ 证书)      │ │                      │               │</span></span>
<span class="line"><span>│ │  │ └──────────┘ └──────────────────────┘               │</span></span>
<span class="line"><span>│ │  │ ┌──────────────────────────────────┐               │</span></span>
<span class="line"><span>│ │  │ │ 底部工具窗岛（监控 | SFTP，头 41）  │               │</span></span>
<span class="line"><span>│ │  │ └──────────────────────────────────┘               │</span></span>
<span class="line"><span>│ └──┘                                                    │</span></span>
<span class="line"><span>│ ┌────────────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>│ │ 状态栏岛（28，bar-arc 12）                           │   │</span></span>
<span class="line"><span>│ └────────────────────────────────────────────────────┘   │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>左条通高</strong>：自主工具栏岛下缘到状态栏岛上缘，高度固定；底部 工具窗岛展开只压缩中心区（中央列内部），不压缩左条。</li><li>监控与 SFTP <strong>同岛不同标签</strong>（产品决策：底部工具窗聚合）；两面板 同时挂载、<code>v-show</code> 切换（保监控选择态与 SFTP 浏览状态）。</li><li>中心岛<strong>永不收起</strong>——终端是一等公民，无会话时显示富空态。</li></ul><h3 id="_3-2-间隙三规则-沿-gmark-定稿" tabindex="-1">3.2 间隙三规则（沿 GMark 定稿） <a class="header-anchor" href="#_3-2-间隙三规则-沿-gmark-定稿" aria-label="Permalink to &quot;3.2 间隙三规则（沿 GMark 定稿）&quot;">​</a></h3><ol><li><strong>岛间留白 = <code>--island-bw</code>（6px）</strong>，由 flex <code>gap</code> 提供；画布四周 padding 同值；所有接缝等宽。</li><li><strong>左条常驻</strong>——隐藏的是左工具窗岛，不是条；条是唤回入口。</li><li><strong>隐藏面板不得叠加间隙</strong>——0 尺寸的工具窗以负 margin 吃掉自身占位 的容器 gap（<code>margin-right: -island-bw</code>），margin 与尺寸同步过渡 （300ms），滑入滑出无跳变。不做则接缝翻倍（6→12px）。</li></ol><h3 id="_3-3-拖拽热区-分割条" tabindex="-1">3.3 拖拽热区（分割条） <a class="header-anchor" href="#_3-3-拖拽热区-分割条" aria-label="Permalink to &quot;3.3 拖拽热区（分割条）&quot;">​</a></h3><ul><li>热区 = 岛间画布留白上的独立元素：<strong>可见宽度 6px</strong>（负 margin 抵消 相邻 gap，与非拖拽接缝视觉一致），命中区经透明伪元素两侧各扩 4px （总 14px）。</li><li>悬停/按住显示 <code>--selection</code> 色提示。</li><li>左工具窗宽 150–600；底部工具窗高 80–600；尺寸持久化 （localStorage <code>vshell:layout</code>），加载时钳制。</li></ul><h3 id="_3-4-面板显隐" tabindex="-1">3.4 面板显隐 <a class="header-anchor" href="#_3-4-面板显隐" aria-label="Permalink to &quot;3.4 面板显隐&quot;">​</a></h3><ul><li>条按钮点击 = toggle（同视图再点收起）；重开恢复「最后视图」 （activeSidebar 记忆）。</li><li>显隐动画 300ms（宽/高 + 负 margin 过渡）。</li><li><code>⌘B</code> 翻转左工具窗；状态栏右侧有三个面板快速开关（active 高亮）。</li></ul><h3 id="_3-5-红绿灯-macos-原生" tabindex="-1">3.5 红绿灯（macOS 原生） <a class="header-anchor" href="#_3-5-红绿灯-macos-原生" aria-label="Permalink to &quot;3.5 红绿灯（macOS 原生）&quot;">​</a></h3><ul><li>无边框窗口（<code>MacTitleBarHiddenInset</code> + <code>InvisibleTitleBarHeight 48</code>， 对齐 GMark）。<code>HiddenInset</code> 会安装一个透明 NSToolbar，macOS 自动把 红绿灯在工具栏条内垂直居中——与 40px 自绘工具栏视觉对齐（实测偏差 ≤1px）；纯 <code>MacTitleBarHidden</code> 下灯位固定在系统 28pt 标题栏中线， 会高出工具栏中线约 12px。<code>InvisibleTitleBarHeight 48</code> 仅为顶部原生 拖拽热区高度（40px 工具栏 + 6px 岛缝）。主工具栏岛左侧预留 <code>--traffic-light-w</code>（76px），区内不放置任何交互元素。</li><li>主工具栏岛为<strong>唯一窗口拖拽区</strong>（<code>-webkit-app-region: drag</code>，双击 最大化）；工具栏内按钮 <code>no-drag</code>。</li></ul><hr><h2 id="_4-组件规范" tabindex="-1">4. 组件规范 <a class="header-anchor" href="#_4-组件规范" aria-label="Permalink to &quot;4. 组件规范&quot;">​</a></h2><blockquote><p>壳层自绘组件位于 <code>components/shell/</code>，前缀 V*；表单/弹窗/下拉/ 消息等交互控件一律 Naive UI（经 §2.1 桥接），不自绘。</p></blockquote><h3 id="_4-1-viconbutton" tabindex="-1">4.1 VIconButton <a class="header-anchor" href="#_4-1-viconbutton" aria-label="Permalink to &quot;4.1 VIconButton&quot;">​</a></h3><ul><li>尺寸 sm=24 / md=28 / lg=40（左条用 lg，图标 20）；悬停 <code>--hover-overlay</code>、按下 <code>--pressed-overlay</code>、active = accent 实底 白图标。</li><li>工具窗头动作一律用它（刷新/新建/折叠/更多…），不做面板内宽按钮。</li></ul><h3 id="_4-2-vstripe-左条" tabindex="-1">4.2 VStripe（左条） <a class="header-anchor" href="#_4-2-vstripe-左条" aria-label="Permalink to &quot;4.2 VStripe（左条）&quot;">​</a></h3><ul><li>宽 40 常驻，<strong>通高</strong>（工具栏岛下缘到状态栏岛上缘，不随底部工具窗 展开而压缩）；40×40 按钮；顶部 = 五个左工具窗入口（连接/密钥/SSH 配置/端口转发/证书），底部 = 监控、SFTP（激活高亮）+ 设置齿轮。</li><li>激活态 = accent 实底圆角 8 + 白图标（Islands 语言；<strong>不是</strong>左侧 2px 指示条）。</li><li>tooltip 全部走 i18n。</li></ul><h3 id="_4-3-vtoolwindow-工具窗壳" tabindex="-1">4.3 VToolWindow（工具窗壳） <a class="header-anchor" href="#_4-3-vtoolwindow-工具窗壳" aria-label="Permalink to &quot;4.3 VToolWindow（工具窗壳）&quot;">​</a></h3><ul><li>圆角 <code>--island-arc</code>（12）；头 41：标题（<strong>基准 −1 = 12px</strong>，IDEA medium 档，secondary，常规字重——相对偏移 \`calc(var(--font-size-base) <ul><li>1px)<code>，跟随用户字号缩放）+ </code>#tabs<code>槽（底部工具窗的 监控|SFTP 药丸标签，靠左紧跟标题，间距</code>--space-3<code>）+ </code>#actions\` 槽（VIconButton 24px）+ 隐藏钮（<strong>短横线 minus 图标</strong>，Hide 语义，非关闭 X）。</li></ul></li><li>收起 = 尺寸到 0 + 负 margin（§3.2-3），300ms，overflow hidden， 禁 display:none / v-if 卸载。</li><li>面板自身的历史「头部行」上移为 <code>#actions</code> 动作钮（消灭各面板重复 的头部条与 <code>.panel-action-btn</code>）。</li></ul><h3 id="_4-4-标签语言-中心岛会话标签" tabindex="-1">4.4 标签语言（中心岛会话标签） <a class="header-anchor" href="#_4-4-标签语言-中心岛会话标签" aria-label="Permalink to &quot;4.4 标签语言（中心岛会话标签）&quot;">​</a></h3><ul><li>行 <code>--tab-row-h</code>（40）不横滚；标签 = <strong>32px 高、四角 8px 圆角矩形 填充块</strong>，垂直居中浮于行内（Islands 激活语言；<strong>不是</strong>下划线）。</li><li>状态：默认透明、文字 0.75 透明度 → 悬停 <code>--hover-gray</code> → 激活 <code>--tab-selected-bg</code>。</li><li><strong>标签间留间距 6px</strong>（<code>--space-3</code>）——圆角填充块贴死会糊成一条。</li><li>单标签 ≤300（截断 + tooltip）。</li><li><strong>超宽折叠（GMark GEditorTabs 同款，IDEA「放不下即隐藏」）</strong>：标签 <strong>保自然宽度不缩水</strong>（<code>flex:0 0 auto</code>；极窄行经 <code>--v-tab-max</code> 随行 收缩，下限 100）；放不下的按 <strong>LRU（激活 → 最近使用 → 原始序）折叠 隐藏</strong>（激活标签恒可见）；被折叠标签脱离流但仍可测量（隐藏于 -9999px）。行右端出现「全部标签」下拉钮（列表项含状态点 / 前缀 色标 / 脏点，选中即激活并回带显示）；行内<strong>滚轮 = 按最近使用序平移 可见窗口</strong>（skip ±1）。面板宽度 / 标签数 / 标题 / 字体变化时重算 （ResizeObserver 逐标签 + 行观察）。</li><li>终端标签：7px 状态点（<code>--status-online</code> / <code>--status-offline</code>）+ 标题。</li><li>编辑器标签：<code>[远程]</code>/<code>[本地]</code> 前缀色标（<code>--color-info</code> / <code>--color-success</code>）+ <strong>脏点与关闭钮同位叠放</strong>：脏且未悬停显小点 （纯指示器不可点），悬停小点让位给关闭钮；关闭钮 <code>visibility</code> 切换（禁 display:none），20px 命中 / 16px 图标 / <code>padding: 0</code>。</li><li>右键菜单：复制会话 / 重连 / 断开 / 关闭 / 关闭其它 / 关闭全部 （NDropdown）。</li><li>无「+」新建钮——终端会话从连接树双击创建。</li></ul><h3 id="_4-5-vstatusbar-状态栏岛" tabindex="-1">4.5 VStatusBar（状态栏岛） <a class="header-anchor" href="#_4-5-vstatusbar-状态栏岛" aria-label="Permalink to &quot;4.5 VStatusBar（状态栏岛）&quot;">​</a></h3><ul><li>高 28，<code>bar-arc</code> 圆角；左中右三区： <ul><li><strong>左</strong>：活动连接名 + 状态点 + 状态文字（四态文案）+ 会话计数 <code>{n} 个会话</code>。纯显示。</li><li><strong>中</strong>：传输摘要（文件名 · 百分比 · 速度，tabular-nums；来自 transfers store），点击直达底部 SFTP 标签；空闲时隐藏。</li><li><strong>右</strong>：左面板 / 监控 / SFTP 三个开关钮（active 高亮）。</li></ul></li><li>部件间距 <code>--space-3</code>；文字 <code>--font-size-xs</code>。</li></ul><h3 id="_4-6-naive-基座约定" tabindex="-1">4.6 Naive 基座约定 <a class="header-anchor" href="#_4-6-naive-基座约定" aria-label="Permalink to &quot;4.6 Naive 基座约定&quot;">​</a></h3><ul><li>弹窗（NModal）圆角 12、内边距沿 Naive；下拉/菜单圆角 8； tooltip 深色反转（<code>--bg-inverted</code>）。</li><li>表单控件高度 28（Naive medium）；密度紧凑处用 small（24）。</li><li>禁止浏览器原生 <code>alert/confirm/prompt</code>——一律 <code>useMessage</code> / <code>useDialog</code>。</li></ul><hr><h2 id="_5-终端区-中心岛" tabindex="-1">5. 终端区（中心岛） <a class="header-anchor" href="#_5-终端区-中心岛" aria-label="Permalink to &quot;5. 终端区（中心岛）&quot;">​</a></h2><ul><li>中心岛 = 会话标签行（§4.4）+ 内容堆叠 + 富空态（无会话时）。</li><li><strong>保活契约</strong>：所有会话视图同时挂载于 absolute 堆叠 （<code>absolute inset-0 invisible pointer-events-none</code> → 激活 <code>!visible !pointer-events-auto</code>），<strong>禁 v-if / display:none</strong>—— 切换标签不丢滚动缓冲与 WebGL 上下文。</li><li>内容视图必须 <code>flex:1; min-width:0</code>——否则按内容收缩、xterm fit 按 窄宽算列数、内容折成窄列。</li><li>xterm 初始化管线不动：ResizeObserver → fit + rAF 延迟首绘 + <code>term.refresh</code>（WebGL 0 高度重绘 bug 规避）。</li><li>终端 I/O 走 Wails Events（<code>terminal:stdin/stdout/resize</code>）， 红线不变。</li><li>断开会话：状态点转 <code>--status-offline</code>，终端内黄字提示 + 回车重连。</li><li>Monaco 编辑器标签（远程文件 / 本地文件 / ssh config 原文）与终端 标签同款视觉；<code>⌘S</code> 保存；脏点语义见 §4.4。</li></ul><hr><h2 id="_6-sftp-底部工具窗" tabindex="-1">6. SFTP（底部工具窗） <a class="header-anchor" href="#_6-sftp-底部工具窗" aria-label="Permalink to &quot;6. SFTP（底部工具窗）&quot;">​</a></h2><ul><li>双栏 commander：左远程（弹性 6）/ 右本地（弹性 4），中缝可拖。</li><li>每栏：面包屑路径（双击进入编辑）+ 目录树 + 可排序文件表；行 24 节奏；选中 <code>--selection</code>；悬停 <code>--hover</code>。</li><li>传输条（底部）：方向色 <code>--transfer-up</code> / <code>--transfer-down</code>、 百分比 tabular-nums；全部完成 2s 后自动收起。</li><li>拖拽语义：远程↔本地互拖、OS 文件拖入上传（<code>native:file-drop</code>）、 ghost 用 <code>--bg-inverted</code> + 圆角 8。</li><li>打开远程文件 → 中心岛编辑器标签（<code>[远程]</code> 前缀）。</li><li>无活动连接时显示轻空态。</li></ul><h2 id="_7-服务器监控-底部工具窗" tabindex="-1">7. 服务器监控（底部工具窗） <a class="header-anchor" href="#_7-服务器监控-底部工具窗" aria-label="Permalink to &quot;7. 服务器监控（底部工具窗）&quot;">​</a></h2><ul><li>左列 280px：主机信息、运行时长、CPU/内存/磁盘状态条（轨道 <code>--stat-bar-track</code>、条高 6 圆角 3、阈值色 success/warning-accent/error）、Top5 进程（可点选）。</li><li>右侧详情：CPU 核心、内存、磁盘、网络（ECharts 折线 + 接口/进程 表）。</li><li><strong>ECharts 纪律</strong>：色值经 <code>cssVar()</code> 解析（canvas 不认 <code>var()</code>）； 主题切换 watch 重渲；容器 ResizeObserver 里补 <code>chartInstance.resize()</code>； 面板隐藏（offsetParent === null）时跳过渲染，显现后 nextTick 重渲。</li></ul><h2 id="_8-连接树-左工具窗" tabindex="-1">8. 连接树（左工具窗） <a class="header-anchor" href="#_8-连接树-左工具窗" aria-label="Permalink to &quot;8. 连接树（左工具窗）&quot;">​</a></h2><ul><li>行高：分组行 24（单行）；连接行<strong>双行</strong>自适应（约 34，<code>node-props</code> 挂 <code>.conn-node</code> 类区分）；层级缩进 8px（<code>NTree :indent</code>，紧凑树）； 分组可折叠（点箭头或双击分组行切换）；拖拽调整归属；双击连接即连接。</li><li>全行选中圆角 8、<code>--selection</code>；悬停 <code>--hover</code>。</li><li>连接行双行内容：状态点 + 名称（主色，截断）⏎ host:port （<code>--text-muted</code>，截断）+ 悬停动作钮（连接/编辑/删除，24px 命中）。</li><li>状态点<strong>只报在线</strong>：在线 = <code>--status-online</code> 绿点；未连接不显点 （保留占位）。<strong>前缀占位统一</strong>：分组图标 14px / 70% 透明；状态点 7px 居中于 14px 槽——两者间距均 4px，分组行与连接行文字起点对齐。</li><li>已连接连接用 <code>--status-online</code> 点标识；连接中 <code>--status-connecting</code>。</li><li>新建/重命名分组走行内输入，不弹窗。</li><li>其余左工具窗（密钥/SSH 配置/端口转发/证书）同规范：行 24、动作 归工具窗头 <code>#actions</code>、状态用 <code>--status-*</code> / 语义色。</li></ul><h2 id="_9-设置" tabindex="-1">9. 设置 <a class="header-anchor" href="#_9-设置" aria-label="Permalink to &quot;9. 设置&quot;">​</a></h2><ul><li>保留模态形态（单窗口工具，非 IDE 多窗口）：NModal 520，三标签 「界面 / 终端 / 快捷键」，改动即时保存 localStorage。</li><li>界面：字体、字号（11–18）。<strong>无主题色选择器</strong>（单一品牌蓝，见 §12-6）。</li><li>终端：字体、字号（10–24）、配色方案（7 项注册表）。</li><li>快捷键：7 项可自定义（按键捕获 + 重置）。</li><li>主题与语言切换在主工具栏岛右侧常驻。</li></ul><h2 id="_10-交互模型" tabindex="-1">10. 交互模型 <a class="header-anchor" href="#_10-交互模型" aria-label="Permalink to &quot;10. 交互模型&quot;">​</a></h2><h3 id="_10-1-键位表" tabindex="-1">10.1 键位表 <a class="header-anchor" href="#_10-1-键位表" aria-label="Permalink to &quot;10.1 键位表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>键</th></tr></thead><tbody><tr><td>切换主题</td><td><code>⌘/Ctrl+Shift+T</code></td></tr><tr><td>切换左工具窗</td><td><code>⌘/Ctrl+B</code></td></tr><tr><td>新建连接（占位待接线）</td><td><code>⌘/Ctrl+Shift+N</code></td></tr><tr><td>关闭标签</td><td><code>⌘/Ctrl+W</code>（原生菜单）</td></tr><tr><td>设置</td><td><code>⌘,</code>（原生菜单）</td></tr><tr><td>保存（编辑器）</td><td><code>⌘/Ctrl+S</code>（原生菜单）</td></tr><tr><td>复制/粘贴（终端内）</td><td>macOS <code>⌘C/⌘V</code>；Win/Linux <code>Ctrl+Shift+C/V</code></td></tr></tbody></table><ul><li>输入框/文本域聚焦时全局快捷键自动跳过；终端内按键透传远端。</li><li>原生菜单动作经 Wails Events（<code>menu:settings/save/close-tab</code>）。</li></ul><h3 id="_10-2-esc-语义" tabindex="-1">10.2 Esc 语义 <a class="header-anchor" href="#_10-2-esc-语义" aria-label="Permalink to &quot;10.2 Esc 语义&quot;">​</a></h3><p>弹窗（Naive）内 Esc = 取消/关闭；终端聚焦时 Esc 透传远端，不被 UI 捕获。</p><h2 id="_11-状态设计" tabindex="-1">11. 状态设计 <a class="header-anchor" href="#_11-状态设计" aria-label="Permalink to &quot;11. 状态设计&quot;">​</a></h2><ul><li><strong>连接四态</strong>：connecting（黄点+「连接中…」）/ online（绿点+「在线」）/ offline（灰点+「已断开」）/ error（红点+「错误」）。三处同色：树、 标签、状态栏。</li><li><strong>富空态</strong>（中心岛无会话）：标题 + 操作提示 + 快捷键提示（「在连接 面板中双击连接即可开始」）。</li><li><strong>轻空态</strong>（SFTP 无连接 / 监控无数据 / 列表无匹配）：一行文字 + 图标。</li><li>通知走 Naive message/dialog；进度反馈优先内联（传输条/状态栏摘要）， 短任务不弹模态。</li></ul><h2 id="_12-与-idea-gmark-参考的差异决策记录" tabindex="-1">12. 与 IDEA / GMark 参考的差异决策记录 <a class="header-anchor" href="#_12-与-idea-gmark-参考的差异决策记录" aria-label="Permalink to &quot;12. 与 IDEA / GMark 参考的差异决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>参考</th><th>vShell 决策</th><th>原因</th></tr></thead><tbody><tr><td>1</td><td>GMark 全自绘 G* 组件家族</td><td><strong>Naive UI 基座 + V* 壳</strong>（仅条/工具窗/标签/状态栏自绘）</td><td>vShell 表单密集（连接/密钥/证书/转发/设置），Naive 已有基建与主题桥接；自绘壳只做岛式语言</td></tr><tr><td>2</td><td>GMark 双侧对称（工作区/制品区）</td><td><strong>单左条 + 底部聚合</strong></td><td>SSH 客户端单工作区；监控与 SFTP 共岛标签（产品决策）</td></tr><tr><td>3</td><td>GMark 两个独立终端面板</td><td><strong>单中心岛多标签</strong></td><td>终端是主体而非附件；FinalShell 用户习惯</td></tr><tr><td>4</td><td>GMark/IDEA 设置独立窗口</td><td><strong>设置保留模态</strong></td><td>单窗口工具形态；避免多窗口管理成本</td></tr><tr><td>5</td><td>IDEA 状态栏 Git 部件</td><td><strong>连接状态 + 传输摘要 + 面板开关</strong></td><td>领域不同：连接状态即「分支」</td></tr><tr><td>6</td><td>vShell 旧版 8 色主题色板（占位）</td><td><strong>移除</strong>，单一品牌蓝</td><td>岛式 accent 是联动色组（primary/selection/tab-selected/hover × 亮暗），单 hex 无法派生六个伴生值</td></tr><tr><td>7</td><td>IDEA 暗色边框 <code>#1E1F22</code></td><td><strong>提亮为 <code>#323538</code></strong></td><td>vShell 在岛内画 1px 分隔线，<code>#1E1F22</code> 在 <code>#1E1F22</code> 岛上不可见</td></tr><tr><td>8</td><td>GMark 编辑器双标签系统（文件+AI 会话）</td><td><strong>单标签系统</strong>（终端+编辑器混排）</td><td>无 AI 会话域；编辑器标签即临时文档</td></tr><tr><td>9</td><td>IDEA 键位体系（速度搜索/双 Shift）</td><td><strong>暂不引入</strong>，保留现有 7 项</td><td>工具体量小，先行保持简单；列为后续候选</td></tr><tr><td>10</td><td>GMark 标签「+」新建</td><td><strong>无「+」</strong></td><td>会话从连接树创建，语义不同</td></tr></tbody></table><h2 id="_13-代码索引" tabindex="-1">13. 代码索引 <a class="header-anchor" href="#_13-代码索引" aria-label="Permalink to &quot;13. 代码索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>位置（artifacts 分支 <code>frontend/src/</code>）</th></tr></thead><tbody><tr><td>Token 单源</td><td><code>styles/global.css</code></td></tr><tr><td>UnoCSS 映射</td><td><code>uno.config.ts</code></td></tr><tr><td>Naive 桥接</td><td><code>App.vue</code>（getComputedStyle 现读注入）</td></tr><tr><td>应用壳</td><td><code>components/shell/</code>（AppShell · ToolbarIsland · LeftStripe · ToolWindow · EditorIsland · EditorTabs · StatusBarIsland）</td></tr><tr><td>布局状态</td><td><code>stores/layout.ts</code>（持久化 <code>vshell:layout</code>）</td></tr><tr><td>终端</td><td><code>components/terminal/</code>（XTerminal · EditorTab）+ <code>composables/useTerminalManager.ts</code></td></tr><tr><td>SFTP</td><td><code>components/sftp/</code>（SFTPPanel · SFTPArea）+ <code>composables/useDragTransfer.ts</code></td></tr><tr><td>监控</td><td><code>components/monitor/MonitorPanel.vue</code></td></tr><tr><td>连接树</td><td><code>components/sidebar/</code>（ConnectionTree · ConnectionFormModal）</td></tr><tr><td>其余左工具窗</td><td><code>components/keys/</code> · <code>components/config/</code> · <code>components/panels/PortForwardPanel.vue</code> · <code>components/cert/</code></td></tr><tr><td>设置</td><td><code>components/settings/SettingsModal.vue</code></td></tr><tr><td>分割条</td><td><code>components/common/DraggableDivider.vue</code></td></tr></tbody></table><hr><p><em>本文档与 artifacts 分支界面重写同步定稿；后续修改设计时先改这里再改代码。</em></p>`,96)])])}const u=d(c,[["render",r]]);export{g as __pageData,u as default};
